// Per-state county bird-frequency loader. Each freq_<xx>.js is its own lazy
// chunk (generated by scripts/splitBirdFreq.mjs), so opening a state park
// fetches ~25KB for THAT state instead of the old 12MB all-states monolith.
// The literal import map below is what lets Vite emit one chunk per state.
const LOADERS = {
  al: () => import('./freq_al.js'), ak: () => import('./freq_ak.js'),
  az: () => import('./freq_az.js'), ar: () => import('./freq_ar.js'),
  ca: () => import('./freq_ca.js'), co: () => import('./freq_co.js'),
  ct: () => import('./freq_ct.js'), de: () => import('./freq_de.js'),
  fl: () => import('./freq_fl.js'), ga: () => import('./freq_ga.js'),
  hi: () => import('./freq_hi.js'), id: () => import('./freq_id.js'),
  il: () => import('./freq_il.js'), in: () => import('./freq_in.js'),
  ia: () => import('./freq_ia.js'), ks: () => import('./freq_ks.js'),
  ky: () => import('./freq_ky.js'), la: () => import('./freq_la.js'),
  me: () => import('./freq_me.js'), md: () => import('./freq_md.js'),
  ma: () => import('./freq_ma.js'), mi: () => import('./freq_mi.js'),
  mn: () => import('./freq_mn.js'), ms: () => import('./freq_ms.js'),
  mo: () => import('./freq_mo.js'), mt: () => import('./freq_mt.js'),
  ne: () => import('./freq_ne.js'), nv: () => import('./freq_nv.js'),
  nh: () => import('./freq_nh.js'), nj: () => import('./freq_nj.js'),
  nm: () => import('./freq_nm.js'), ny: () => import('./freq_ny.js'),
  nc: () => import('./freq_nc.js'), nd: () => import('./freq_nd.js'),
  oh: () => import('./freq_oh.js'), ok: () => import('./freq_ok.js'),
  or: () => import('./freq_or.js'), pa: () => import('./freq_pa.js'),
  ri: () => import('./freq_ri.js'), sc: () => import('./freq_sc.js'),
  sd: () => import('./freq_sd.js'), tn: () => import('./freq_tn.js'),
  tx: () => import('./freq_tx.js'), ut: () => import('./freq_ut.js'),
  vt: () => import('./freq_vt.js'), va: () => import('./freq_va.js'),
  wa: () => import('./freq_wa.js'), wv: () => import('./freq_wv.js'),
  wi: () => import('./freq_wi.js'), wy: () => import('./freq_wy.js'),
  // Puerto Rico — 5 NWRs in US-PR-### municipios; no state parks, so this
  // chunk exists purely for the federal-unit bird floor.
  pr: () => import('./freq_pr.js'),
};

// One state's data ({ PARK_COUNTY, COUNTY_BIRD_FREQ }) or null. Repeated
// calls are cheap — the browser caches dynamic-import modules.
export async function loadStateBirdFreq(stateCode) {
  const load = LOADERS[String(stateCode ?? '').toLowerCase()];
  if (!load) return null;
  try { return await load(); } catch { return null; }
}

// All states merged — used by the universal species search, which inverts the
// whole dataset by design (same total bytes as the old monolith, but each
// chunk lands in the module cache, so panel opens afterwards are free).
export async function loadAllBirdFreq() {
  const mods = await Promise.all(Object.values(LOADERS).map(l => l().catch(() => null)));
  const PARK_COUNTY = {}, COUNTY_BIRD_FREQ = {};
  for (const m of mods) {
    if (!m) continue;
    Object.assign(PARK_COUNTY, m.PARK_COUNTY);
    Object.assign(COUNTY_BIRD_FREQ, m.COUNTY_BIRD_FREQ);
  }
  return { PARK_COUNTY, COUNTY_BIRD_FREQ };
}
